<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { showFailToast, showSuccessToast } from 'vant'; import { useRoute, useRouter } from 'vue-router'; import { api, type Expense, type Sale } from '../api'; import { useWorkspaceStore } from '../stores/workspace'; import { formatDateTime } from '../utils/dateTime'; import AppBottomNavigation from '../components/AppBottomNavigation.vue';
const route=useRoute();const router=useRouter();const store=useWorkspaceStore();const batchId=computed(()=>String(route.params.id));const tab=ref<'sales'|'expenses'>('sales');const sales=ref<Sale[]>([]);const expenses=ref<Expense[]>([]);const loading=ref(true);const error=ref('');const showReverse=ref(false);const reverseType=ref<'sale'|'expense'>('sale');const reverseId=ref('');const reverseReason=ref('');const reversing=ref(false);const canEdit=computed(()=>{const b=store.batches.find((x)=>x.id===batchId.value);return Boolean(b&&(b.role==='owner'||b.role==='editor'||store.canManageWorkspace));});
async function load(){loading.value=true;error.value='';try{const [s,e]=await Promise.all([api.get<Sale[]>(`/batches/${batchId.value}/sales`),api.get<Expense[]>(`/batches/${batchId.value}/expenses`)]);sales.value=s.data;expenses.value=e.data;}catch{error.value='交易记录加载失败，请重试';}finally{loading.value=false;}}function openSale(saleId:string){void router.push(`/batches/${batchId.value}/transactions/sales/${saleId}`);}function ask(type:'sale'|'expense',id:string){reverseType.value=type;reverseId.value=id;reverseReason.value='';showReverse.value=true;}async function reverse(){if(!reverseReason.value.trim())return showFailToast('请填写撤销原因');reversing.value=true;try{await api.post(`/batches/${batchId.value}/${reverseType.value==='sale'?'sales':'expenses'}/${reverseId.value}/reversals`,{reason:reverseReason.value.trim()});showReverse.value=false;showSuccessToast('已撤销');await load();}catch(e:unknown){showFailToast((e as {response?:{data?:{message?:string}}}).response?.data?.message||'撤销失败');}finally{reversing.value=false;}}onMounted(async()=>{if(!store.workspaces.length)await store.load();await load();});
</script>
<template><div class="transaction-page" data-ai-id="transaction-page"><van-nav-bar title="交易" left-text="返回" left-arrow @click-left="router.push(`/batches/${batchId}`)"/><div v-if="loading" class="state"><van-loading/></div><van-empty v-else-if="error" :description="error"/><main v-else class="content"><div class="tabs"><button :class="{active:tab==='sales'}" @click="tab='sales'">销售</button><button :class="{active:tab==='expenses'}" @click="tab='expenses'">费用</button></div><section v-if="tab==='sales'" data-ai-id="sale-list"><header><span>实际收款记在卖出人名下</span><van-button v-if="canEdit" size="small" type="primary" @click="router.push(`/batches/${batchId}/transactions/sales/new`)">记录销售</van-button></header><van-empty v-if="!sales.length" description="还没有销售记录"/><article v-for="sale in sales" :key="sale.id" class="item sale-item" tabindex="0" role="button" :aria-label="`查看${sale.displayName || sale.productName}销售详情`" :data-ai-id="`sale-item-${sale.id}`" @click="openSale(sale.id)" @keydown.enter="openSale(sale.id)"><div class="item-main"><strong>{{sale.displayName || sale.productName}} · ¥{{sale.totalPrice}}</strong><span>{{sale.sellerUsername}} 实收 ¥{{ sale.receivedAmount }} · {{sale.quantity}} 件</span><small>手续费 ¥{{ sale.serviceFee }}{{ sale.salesChannel ? ` · ${sale.salesChannel}` : '' }} · {{formatDateTime(sale.occurredAt)}}</small></div><div class="item-side"><van-tag v-if="sale.reversalReason" type="default" class="status-tag status-tag--reversed" :data-ai-id="`sale-status-${sale.id}`">已撤销</van-tag><van-tag v-else-if="sale.settled" type="success" class="status-tag status-tag--settled" :data-ai-id="`sale-status-${sale.id}`">已结账</van-tag><button v-else-if="canEdit" class="reverse" title="撤销销售" :data-ai-id="`sale-reversal-${sale.id}`" @click.stop="ask('sale',sale.id)">撤销</button></div></article></section><section v-else data-ai-id="expense-list"><header><span>记录谁实际垫付的费用</span><van-button v-if="canEdit" size="small" type="primary" @click="router.push(`/batches/${batchId}/transactions/expenses/new`)">记录费用</van-button></header><van-empty v-if="!expenses.length" description="还没有费用记录"/><article v-for="expense in expenses" :key="expense.id" class="item" :data-ai-id="`expense-item-${expense.id}`"><div class="item-main"><strong>{{expense.name}} · ¥{{expense.amount}}</strong><span>{{expense.payerUsername}} 付款</span></div><div class="item-side"><van-tag v-if="expense.reversalReason" type="default" class="status-tag status-tag--reversed" :data-ai-id="`expense-status-${expense.id}`">已撤销</van-tag><van-tag v-else-if="expense.settled" type="success" class="status-tag status-tag--settled" :data-ai-id="`expense-status-${expense.id}`">已结账</van-tag><button v-else-if="canEdit" class="reverse" title="撤销费用" :data-ai-id="`expense-reversal-${expense.id}`" @click="ask('expense',expense.id)">撤销</button></div></article></section></main><van-dialog v-model:show="showReverse" :title="reverseType==='sale'?'撤销销售':'撤销费用'" show-cancel-button @confirm="reverse"><van-field v-model="reverseReason" label="撤销原因" type="textarea" rows="2"/></van-dialog><AppBottomNavigation/></div></template>
<style scoped>.transaction-page{min-height:100vh;padding-bottom:66px;background:#f7f9fc}.content{padding:16px}.tabs{display:grid;grid-template-columns:1fr 1fr;margin-bottom:14px;overflow:hidden;border:1px solid #dfe5ee;border-radius:9px;background:#fff}.tabs button,.reverse{min-height:44px;border:0;background:transparent;font:inherit}.tabs button{color:#61708a}.tabs button.active{background:#eef2ff;color:#3657c8;font-weight:600}.content header{display:flex;align-items:center;justify-content:space-between;min-height:44px;color:#71809a;font-size:12px}.item{display:flex;min-height:82px;align-items:center;justify-content:space-between;gap:10px;margin-top:8px;padding:12px;border:1px solid #edf0f5;border-radius:10px;background:#fff}.sale-item{cursor:pointer}.sale-item:focus-visible{outline:2px solid #3657c8;outline-offset:2px}.item-main{min-width:0;flex:1}.item-side{display:flex;flex:0 0 auto;align-items:center;justify-content:flex-end;min-width:62px}.item strong,.item span,.item small{display:block}.item span,.item small{margin-top:4px;color:#71809a;font-size:12px}.item-side :deep(.status-tag){display:inline-flex;align-items:center;justify-content:center;min-width:42px;height:22px;padding:0 7px;border:0;border-radius:4px;font-size:11px;font-weight:500}.item-side :deep(.status-tag--settled){background:#e7f6ed;color:#21864f}.item-side :deep(.status-tag--reversed){background:#eef0f3;color:#687386}.reverse{color:#b42318}.state{display:grid;min-height:60vh;place-items:center}</style>
